<?php $pageTitle='Financeiro'; require_once __DIR__.'/../../includes/header.php';
$action=$_GET['action']??'';$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$tipo=$_POST['tipo'];$descricao=trim($_POST['descricao']);$valor=(float)$_POST['valor'];$vencimento=$_POST['vencimento'];$status=$_POST['status'];$categoria=trim($_POST['categoria']); if($id){$st=$pdo->prepare('UPDATE financeiro SET tipo=?,descricao=?,valor=?,vencimento=?,status=?,categoria=? WHERE id=?');$st->execute([$tipo,$descricao,$valor,$vencimento,$status,$categoria,$id]);}else{$st=$pdo->prepare('INSERT INTO financeiro(tipo,descricao,valor,vencimento,status,categoria) VALUES(?,?,?,?,?,?)');$st->execute([$tipo,$descricao,$valor,$vencimento,$status,$categoria]);}flash('ok','Lançamento salvo.');header('Location:index.php');exit;}
if($action==='excluir'&&$id){$pdo->prepare('DELETE FROM financeiro WHERE id=?')->execute([$id]);header('Location:index.php');exit;}
$edit=null;if($action==='editar'&&$id){$st=$pdo->prepare('SELECT * FROM financeiro WHERE id=?');$st->execute([$id]);$edit=$st->fetch();}
$rows=$pdo->query('SELECT * FROM financeiro ORDER BY vencimento DESC,id DESC')->fetchAll();$rec=$pdo->query("SELECT COALESCE(SUM(valor),0) FROM financeiro WHERE tipo='RECEITA' AND status<>'CANCELADO'")->fetchColumn();$des=$pdo->query("SELECT COALESCE(SUM(valor),0) FROM financeiro WHERE tipo='DESPESA' AND status<>'CANCELADO'")->fetchColumn(); ?>
<div class="stat-strip"><div class="mini"><span>Receitas</span><strong><?=money($rec)?></strong></div><div class="mini"><span>Despesas</span><strong><?=money($des)?></strong></div><div class="mini"><span>Resultado</span><strong><?=money($rec-$des)?></strong></div></div>
<div class="panel mb-3"><div class="panel-title"><h3>Lançamentos</h3><button class="btn btn-dark btn-sm" data-bs-toggle="collapse" data-bs-target="#form">Novo lançamento</button></div><div class="collapse <?=$edit?'show':''?>" id="form"><form method="post" class="row g-3"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="col-md-2"><label>Tipo</label><select name="tipo" class="form-select"><option>RECEITA</option><option>DESPESA</option></select></div><div class="col-md-4"><label>Descrição</label><input name="descricao" class="form-control" value="<?=e($edit['descricao']??'')?>" required></div><div class="col-md-2"><label>Valor</label><input name="valor" type="number" step="0.01" class="form-control" value="<?=e($edit['valor']??'')?>" required></div><div class="col-md-2"><label>Vencimento</label><input name="vencimento" type="date" class="form-control" value="<?=e($edit['vencimento']??date('Y-m-d'))?>"></div><div class="col-md-2"><label>Status</label><select name="status" class="form-select"><option>PENDENTE</option><option>PAGO</option><option>ATRASADO</option><option>CANCELADO</option></select></div><div class="col-md-4"><label>Categoria</label><input name="categoria" class="form-control" value="<?=e($edit['categoria']??'')?>"></div><div class="col-12"><button class="btn btn-dark">Salvar</button></div></form></div></div>
<div class="panel"><div class="table-responsive"><table class="table"><thead><tr><th>Tipo</th><th>Descrição</th><th>Categoria</th><th>Vencimento</th><th>Status</th><th>Valor</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tipo'])?></td><td><?=e($r['descricao'])?></td><td><?=e($r['categoria'])?></td><td><?=date('d/m/Y',strtotime($r['vencimento']))?></td><td><?=e($r['status'])?></td><td><?=money($r['valor'])?></td><td><a href="?action=editar&id=<?=$r['id']?>">Editar</a> · <a data-confirm="Excluir?" href="?action=excluir&id=<?=$r['id']?>">Excluir</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>